    h = int(observation["grid_height"])
    sx, sy = observation["self_position"]
    obstacles = set(map(tuple, observation.get("obstacles") or []))
    unclaimed = set(map(tuple, observation.get("unclaimed_cells") or []))
    self_terr = set(map(tuple, observation.get("self_territory") or []))
    resources = observation.get("resources") or []
    cx, cy = (w - 1) / 2.0, (h - 1) / 2.0

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def manh(x1, y1, x2, y2):
        dx = x1 - x2
        if dx < 0:
            dx = -dx
        dy = y1 - y2
        if dy < 0:
            dy = -dy
        return dx + dy

    def neigh(x, y):
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if inb(nx, ny) and (nx, ny) not in obstacles:
                    yield nx, ny, dx, dy

    best_targets = []
    if resources:
        targets = [tuple(resources[0])]
        best_targets = targets
    else:
        frontier = []
        if self_terr:
            for x, y in self_terr:
                for nx, ny in [(x + dx, y + dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1) if not (dx == 0 and dy == 0)]:
                    if inb(nx, ny) and (nx, ny) in unclaimed:
                        frontier.append((nx, ny))
        targets = list(dict.fromkeys(frontier))  # deterministic de-dup preserving order
        if not targets:
            # go for nearest unclaimed cell toward center, biased to open space
            targets = list(unclaimed)
        if not targets:
            return [0, 0]
        best_targets = targets

    # Score targets by (closest to us) and (closer to center), prefer those adjacent to our territory if possible
    adj_to_ours = 0
    if self_terr:
        for x, y in best_targets[: min(200, len(best_targets))]:
            for nx in (-1, 0, 1):
                for ny in (-1, 0, 1):
                    if nx == 0 and ny == 0:
                        continue
                    if (x + nx, y + ny) in self_terr:
                        adj_to_ours = 1
                        break
                if adj_to_ours:
                    break
            if adj_to_ours:
                break

    def target_score(t):
        tx, ty = t
        base = manh(sx, sy, tx, ty)
        center = manh(tx, ty, cx, cy)
        bonus_adj = 0
        if self_terr:
            for nx in (-1, 0, 1):
                for ny in (-1, 0, 1):
                    if nx == 0 and ny == 0:
                        continue
                    if (tx + nx, ty + ny) in self_terr:
                        bonus_adj = 3
                        break
                if bonus_adj:
                    break
        return (base - bonus_adj, center, tx, ty)

    target = min(best_targets, key=target_score)
    tx, ty = target

    # Move one step toward target; tie-break by preferring moves that reduce distance most and do not hit obstacles.
    candidates = []
    for nx, ny, dx, dy in neigh(sx, sy):
        score = manh(nx, ny, tx, ty)
        candidates.append((score, abs(dx) + abs(dy), nx, ny, dx, dy))
    if not candidates:
        return [0, 0]
    candidates.sort(key=lambda z: (z[0], z[1], z[2], z[3]))
    _, _, _, _, dx, dy = candidates[0]
    return [int(dx), int(dy)]

